						skyC += uSunColor * (pow(max(dot(T, uSunDir), 0.0), 400.0) * 8.0 + pow(max(dot(T, uSunDir), 0.0), 14.0) * 0.35) * smoothstep(-0.05, 0.1, uSunDir.y);
						// the light let through falls away toward the rim (most of it is reflected there)
